#!/bin/bash
# GPU queue daemon: gpuq.sh <gpu_id>. Pops lines "<name>\t<command>" from queue/gpu<id>.txt (first line first),
# runs each with CUDA_VISIBLE_DEVICES=<id> from ROOT; log logs/<name>.log; marker logs/<name>.done or .failed.
# Stop: touch queue/stop<id>. Do not edit this file while a daemon runs (bash reads lazily).
ROOT=${BREWING_WORKSPACE:-$(cd "$(dirname "$(readlink -f "$0")")/../.." && pwd)}/experiments/gen_depth
G=$1; Q=$ROOT/queue/gpu$G.txt; touch $Q
cd $ROOT
while [ ! -f $ROOT/queue/stop$G ]; do
  line=$(${PYTHON:-python} -c "
import fcntl,sys
p='$Q'
with open(p,'r+') as f:
    fcntl.flock(f, fcntl.LOCK_EX)
    lines=[l for l in f.read().split('\n') if l.strip() and not l.startswith('#')]
    if not lines: sys.exit(0)
    print(lines[0]); f.seek(0); f.truncate(); f.write('\n'.join(lines[1:])+('\n' if lines[1:] else ''))
")
  if [ -z "$line" ]; then sleep 20; continue; fi
  name=$(printf '%s' "$line" | cut -f1); cmd=$(printf '%s' "$line" | cut -f2-)
  echo "$(date '+%F %T') START $name :: $cmd" >> $ROOT/queue/gpu$G.history
  CUDA_VISIBLE_DEVICES=$G bash -c "$cmd" > $ROOT/logs/$name.log 2>&1
  rc=$?
  if [ $rc -eq 0 ]; then touch $ROOT/logs/$name.done; else touch $ROOT/logs/$name.failed; fi
  echo "$(date '+%F %T') END $name rc=$rc" >> $ROOT/queue/gpu$G.history
done
